using System;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Collections.Generic;
using System.Threading.Tasks;
class Tests {
 static string Get(MobileServer server,string path,string cookie=null,string host=null){using(var c=new TcpClient("127.0.0.1",server.Port)){c.ReceiveTimeout=3000;var stream=c.GetStream();string req="GET "+path+" HTTP/1.1\r\nHost: "+(host??"127.0.0.1:"+server.Port)+"\r\n"+(cookie==null?"":"Cookie: mega_phone="+cookie+"\r\n")+"\r\n";var bytes=Encoding.ASCII.GetBytes(req);stream.Write(bytes);return new StreamReader(stream).ReadToEnd();}}
 static void Assert(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Main(string[] args){OptionChainTests.Run();string root=args.Length>0?Path.GetFullPath(args[0]):Directory.GetCurrentDirectory();using(var s=new MobileServer(()=>"{\"symbol\":\"TXFJ6\"}",root)){s.Start();Assert(Get(s,"/api/snapshot").Contains("401 Unauthorized"),"unpaired API");Assert(Get(s,"/").Contains("401 Unauthorized"),"unpaired HTML");Assert(Get(s,"/pair?token=incorrect").Contains("401 Unauthorized"),"invalid token");string url=s.PairUrl("https://example.trycloudflare.com"),token=url.Substring(url.IndexOf("token=")+6);Assert(token.Length==64,"random token length");string paired=Get(s,"/pair?token="+token);Assert(paired.Contains("302 Found")&&paired.Contains("HttpOnly; Secure; SameSite=Lax")&&paired.Contains("Location: /?mode=live"),"secure pair cookie");Assert(Get(s,"/api/snapshot",token).Contains("TXFJ6"),"paired API");Assert(Get(s,"/?mode=live",token).Contains("window.remotePhoneMode=true"),"remote mode");Assert(Get(s,"/speedyAPI_config.json",token).Contains("404 Not Found"),"credential path allowlist");Assert(Get(s,"/../windows-connector/Connector.cs",token).Contains("404 Not Found"),"traversal");Assert(Get(s,"/api/snapshot",token,"evil.example").Contains("400 Bad Request"),"host restriction");Assert(Get(s,"/api/snapshot",new string('0',64)).Contains("401 Unauthorized"),"wrong cookie");s.PublicHost="example.trycloudflare.com";Assert(Get(s,"/api/snapshot",token,s.PublicHost).Contains("TXFJ6"),"tunnel hostname");var jobs=new List<Task>();for(int i=0;i<5;i++)jobs.Add(Task.Run(()=>Assert(Get(s,"/api/snapshot",token).Contains("TXFJ6"),"concurrent client")));Task.WaitAll(jobs.ToArray());typeof(MobileServer).GetField("expires",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(s,DateTime.UtcNow.AddMinutes(-1));Assert(Get(s,"/api/snapshot",token).Contains("401 Unauthorized"),"expired session");Assert(Get(s,"/pair?token="+token).Contains("401 Unauthorized"),"expired pairing");Console.WriteLine("PASS: unpaired access blocked, secure pairing, snapshot, asset allowlist, traversal/host checks, concurrency.");}using(var a=new MobileServer(()=>"{}",root))using(var b=new MobileServer(()=>"{}",root)){Assert(a.PairUrl("x")!=b.PairUrl("x"),"token changes per instance");Console.WriteLine("PASS: tokens rotate on restart.");}}
}
